/** Sequential ids (bk_0001, bk_0002, ...) so runs are reproducible. */
export function sequentialIds(prefix = "bk"): () => string {
  let n = 0;
  return () => `${prefix}_${String(++n).padStart(4, "0")}`;
}

export function createDeps(overrides: Partial<Deps> = {}): Deps {
  return {
    store: overrides.store ?? new BookingStore(),
    clock: overrides.clock ?? systemClock,
    nextId: overrides.nextId ?? sequentialIds(),

      deps,
      request.userId,
      request.headers["idempotency-key"],
      request.body,
    );

    switch (result.kind) {
      case "created":
        return reply.code(201).send(result.booking);
      case "replayed":
        return reply.code(200).header("idempotent-replayed", "true").send(result.booking);
      case "key_reused":
        return reply.code(422).send({ error: "idempotency_key_reused", message: result.message });
      case "rejected":
        return reply
          .code(result.code === "resource_not_found" ? 404 : 400)
          .send({ error: result.code, message: result.message });
    }
  },
);

